<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { api, download } from '../api'
const props=defineProps({kind:String})
const student=computed(()=>props.kind==='students')
const title=computed(()=>student.value?'学生管理':'宿舍管理')
const items=ref([]),total=ref(0),page=ref(1),busy=ref(false),error=ref(''),notice=ref(''),selected=ref([]),buildings=ref([]),floors=ref([])
const query=reactive({name:'',studentId:'',className:'',dormitoryNumber:'',grade:'all',gender:'all',building:'all',roomType:'all',occupancy:'all',floor:'all',sortBy:student.value?'id':'dormitoryNumber',sortOrder:student.value?'desc':'asc'})
const editing=ref(false),editId=ref(null),form=reactive({}),detail=ref(null),assignNo=ref('')
const columns=computed(()=>student.value?[['studentId','学号'],['name','姓名'],['grade','年级'],['className','班级'],['gender','性别'],['phone','手机号'],['dormitoryNumber','宿舍']]:[['dormitoryNumber','宿舍号'],['building','楼栋'],['roomType','房型'],['gender','性别'],['currentCount','已入住'],['capacity','床位'],['remark','备注']])
async function load() {
  busy.value=true; error.value=''
  try { const allowed=student.value?['name','studentId','className','dormitoryNumber','grade','gender','sortBy','sortOrder']:['dormitoryNumber','building','roomType','gender','occupancy','floor','sortBy','sortOrder']; const params=new URLSearchParams({page:page.value,size:10}); allowed.forEach(k=>params.set(k,query[k])); const data=await api('/'+props.kind+'?'+params); items.value=data.items; total.value=data.total; if(data.buildings) buildings.value=data.buildings; selected.value=[] }
  catch(e) { error.value=e.message } finally { busy.value=false }
}
async function filter() { page.value=1; await load() }
function open(item) { Object.keys(form).forEach(k=>delete form[k]); editId.value=item?.id??null; Object.assign(form, student.value?{name:'',studentId:'',grade:'大一',className:'',gender:'男',phone:'',dormitoryNumber:'',initialPassword:''}:{dormitoryNumber:'',building:buildings.value[0]?.name||'',roomType:'四人间',gender:buildings.value[0]?.gender||'男',remark:''}); if(item) columns.value.forEach(([k])=>form[k]=item[k]??''); editing.value=true }
async function save() {
  busy.value=true; error.value=''
  try { const body={...form}; if(student.value&&!body.initialPassword) delete body.initialPassword; await api('/'+props.kind+(editId.value?'/'+editId.value:''),{method:editId.value?'PUT':'POST',body}); editing.value=false; notice.value='保存成功'; await load() }
  catch(e) { error.value=e.message } finally { busy.value=false }
}
async function remove(ids) { if(!confirm(student.value?`确认归档选中的 ${ids.length} 名学生？须先退宿，历史档案将保留。`:`确认删除选中的 ${ids.length} 条记录？`))return; try { await api('/'+props.kind+'/batch-delete',{method:'POST',body:{ids}}); if(page.value>1&&ids.length===items.value.length)page.value--; notice.value=student.value?'归档成功':'删除成功'; await load() } catch(e) { error.value=e.message } }
async function view(item) { try { detail.value=await api('/dormitories/'+item.id) } catch(e) { error.value=e.message } }
async function assign() { try { const data=await api('/students?studentId='+encodeURIComponent(assignNo.value)+'&size=100'); const found=data.items.find(s=>s.studentId===assignNo.value); if(!found)throw Error('未找到该学号，请先添加学生档案'); await api(`/dormitories/${detail.value.dormitory.id}/students/${found.id}`,{method:'POST'}); assignNo.value=''; await view(detail.value.dormitory); await load() } catch(e) { error.value=e.message } }
async function unassign(s) { if(!confirm('确认将该学生移出宿舍？'))return; try { await api(`/dormitories/${detail.value.dormitory.id}/students/${s.id}`,{method:'DELETE'}); await view(detail.value.dormitory); await load() } catch(e) { error.value=e.message } }
async function exportData() { try { await download(props.kind) } catch(e) { error.value=e.message } }
async function updateFloors() { try { query.floor='all'; floors.value=await api('/dormitories/floors?building='+encodeURIComponent(query.building)); await filter() } catch(e) { error.value=e.message } }
function toggleAll(e) { selected.value=e.target.checked?items.value.map(x=>x.id):[] }
onMounted(async()=>{await load(); if(!student.value) await updateFloors()})
</script>
<template>
  <div class="page-heading"><div><span class="eyebrow">{{student?'STUDENTS':'RESIDENCES'}}</span><h1>{{title}}</h1><p class="muted">{{student?'管理学生档案与住宿信息':'查看房间状态，管理床位与入住安排'}}</p></div><div class="actions"><button @click="exportData">导出 Excel</button><button class="primary" @click="open(null)">＋ {{student?'添加学生':'添加宿舍'}}</button></div></div>
  <div v-if="error" class="alert sticky" role="alert">{{error}}<button @click="error=''">关闭</button></div><div v-if="notice" class="notice">{{notice}}</div>
  <section class="card"><form class="filters" @submit.prevent="filter">
    <template v-if="student"><input v-model="query.studentId" placeholder="搜索学号" aria-label="搜索学号"><input v-model="query.name" placeholder="搜索姓名" aria-label="搜索姓名"><input v-model="query.className" placeholder="搜索班级" aria-label="搜索班级"><select v-model="query.grade" aria-label="年级"><option value="all">全部年级</option><option v-for="g in ['大一','大二','大三','大四']" :key="g">{{g}}</option></select></template>
    <template v-else><select v-model="query.building" aria-label="楼栋" @change="updateFloors"><option value="all">全部楼栋</option><option v-for="b in buildings" :key="b.id" :value="b.name">{{b.name}}</option></select><select v-model="query.floor" aria-label="楼层"><option value="all">全部楼层</option><option v-for="f in floors" :key="f" :value="f">{{f}} 层</option></select><select v-model="query.roomType" aria-label="房型"><option value="all">全部房型</option><option>二人间</option><option>四人间</option><option>六人间</option></select><select v-model="query.occupancy" aria-label="入住状态"><option value="all">全部状态</option><option value="empty">空闲</option><option value="not_full">未住满</option><option value="full">已住满</option></select></template>
    <input v-model="query.dormitoryNumber" placeholder="搜索宿舍号" aria-label="搜索宿舍号"><select v-model="query.gender" aria-label="性别"><option value="all">全部性别</option><option>男</option><option>女</option></select><button class="primary" :disabled="busy">查询</button>
  </form><div class="table-toolbar"><span>共 <strong>{{total}}</strong> 条记录</span><div class="actions"><button class="danger-text" :disabled="!selected.length||busy" @click="remove(selected)">{{student?'归档所选':'删除所选'}}（{{selected.length}}）</button><select v-model="query.sortBy" aria-label="排序字段" @change="filter"><option v-for="[key,label] in columns.filter(([k])=>student?['studentId','name','grade','className','gender'].includes(k):!['remark'].includes(k))" :key="key" :value="key">按{{label}}排序</option></select><select v-model="query.sortOrder" aria-label="排序方向" @change="filter"><option value="asc">升序</option><option value="desc">降序</option></select></div></div>
    <div class="table-scroll"><table><thead><tr><th><input type="checkbox" :checked="items.length>0&&selected.length===items.length" aria-label="全选" @change="toggleAll"></th><th v-for="[key,label] in columns" :key="key">{{label}}</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><input v-model="selected" type="checkbox" :value="item.id" aria-label="选中记录"></td><td v-for="[key] in columns" :key="key">{{item[key]??'—'}}<span v-if="key==='dormitoryNumber'&&student&&item.dormitoryLeader" class="badge">宿舍长</span></td><td class="row-actions"><button v-if="!student" class="text-button" @click="view(item)">入住详情</button><button class="text-button" @click="open(item)">编辑</button><button class="text-button danger-text" @click="remove([item.id])">{{student?'归档':'删除'}}</button></td></tr><tr v-if="!items.length"><td :colspan="columns.length+2" class="empty">{{busy?'正在加载…':'暂无符合条件的记录'}}</td></tr></tbody></table></div>
    <div class="pagination"><span>每页 10 条</span><div class="actions"><button :disabled="page<=1||busy" @click="page--;load()">上一页</button><span>{{page}} / {{Math.max(1,Math.ceil(total/10))}}</span><button :disabled="page*10>=total||busy" @click="page++;load()">下一页</button></div></div>
  </section>
  <div v-if="editing" class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" :aria-label="title"><div class="modal-heading"><h2>{{editId?'编辑':'添加'}}{{student?'学生':'宿舍'}}</h2><button @click="editing=false">关闭</button></div><form class="form-grid" @submit.prevent="save">
    <template v-if="student"><label>学号<input v-model="form.studentId" required pattern="[0-9]{4,20}" :disabled="!!editId"></label><label>姓名<input v-model="form.name" required maxlength="50"></label><label>年级<select v-model="form.grade"><option v-for="g in ['大一','大二','大三','大四']" :key="g">{{g}}</option></select></label><label>班级<input v-model="form.className" maxlength="50"></label><label>手机号<input v-model="form.phone" required pattern="1[3-9][0-9]{9}" maxlength="11"></label><label>宿舍号（留空为未入住）<input v-model="form.dormitoryNumber" maxlength="80" placeholder="1号楼-0101"></label><label v-if="!editId">账号初始密码<input v-model="form.initialPassword" type="password" minlength="8" maxlength="72" autocomplete="new-password" placeholder="新账号至少 8 位"></label></template>
    <template v-else><label>楼栋<select v-model="form.building" required @change="form.gender=buildings.find(b=>b.name===form.building)?.gender"><option v-for="b in buildings" :key="b.id" :value="b.name">{{b.name}}</option></select></label><label>完整宿舍号<input v-model="form.dormitoryNumber" required maxlength="80" placeholder="1号楼-0101"></label><label>房型<select v-model="form.roomType"><option>二人间</option><option>四人间</option><option>六人间</option></select></label><label>备注<input v-model="form.remark" maxlength="200"></label></template>
    <label>性别<select v-model="form.gender"><option>男</option><option>女</option></select></label><div class="form-footer"><button type="button" @click="editing=false">取消</button><button class="primary" :disabled="busy">保存</button></div>
  </form></section></div>
  <div v-if="detail" class="modal-backdrop"><section class="modal wide" role="dialog" aria-modal="true" aria-label="宿舍入住详情"><div class="modal-heading"><h2>{{detail.dormitory.dormitoryNumber}} · 入住详情</h2><button @click="detail=null">关闭</button></div><p class="muted">{{detail.dormitory.roomType}} · {{detail.dormitory.gender}}生宿舍 · {{detail.students.length}} / {{detail.dormitory.capacity}} 床位</p><div class="table-scroll"><table><thead><tr><th>学号</th><th>姓名</th><th>班级</th><th>手机号</th><th>操作</th></tr></thead><tbody><tr v-for="s in detail.students" :key="s.id"><td>{{s.studentId}}</td><td>{{s.name}} <span v-if="s.dormitoryLeader" class="badge">宿舍长</span></td><td>{{s.className}}</td><td>{{s.phone}}</td><td><button class="text-button danger-text" @click="unassign(s)">移出宿舍</button></td></tr></tbody></table></div><form class="filters" @submit.prevent="assign"><input v-model="assignNo" required placeholder="输入已建档学生的学号" aria-label="入住学号"><button class="primary">安排入住</button></form></section></div>
</template>
